fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome190 {
    data class Success(val payload: String) : Outcome190()
    data object Failure : Outcome190()
}

fun describe190(outcome: Outcome190): String = when (outcome) {
    is Outcome190.Success -> outcome.payload
    Outcome190.Failure -> "failed"
}
@JvmName("step191")
fun step191(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 65
}
